arguments.new_str:
    // .NET 9 breaking change: GetEnvironmentVariable now returns null for
    // empty env vars on Unix. Use string.IsNullOrEmpty to preserve old behavior,
    // or check /proc/self/environ to distinguish "not set" from "empty".
    var val = Environment.GetEnvironmentVariable("MY_FLAG");
    if (val == null && !IsEnvVarDefined("MY_FLAG"))
    {
        Console.WriteLine("MY_FLAG not set, using default");
    }
}

private static bool IsEnvVarDefined(string name)
{
    // Consult the raw environment block to distinguish "not set" from "set to empty"
    // since .NET 9 returns null for both on Unix.
    try
    {
        var environ = File.ReadAllText("/proc/self/environ");
        return environ.Contains($"{name}=", StringComparison.Ordinal);
    }
    catch
    {
        return false;
    }

